    {
        if ( currentByteIndex == 0 )
        {
            file->read(buffer, BufferSize);
            bytesRead = (FIT_UINT32)file->gcount();
        }

        FIT_UINT32 i = currentByteIndex;
        const FIT_UINT32 n = bytesRead;
        const FIT_UINT32 baseOffset = currentByteOffset - i;

        if ( (i < n) && pause )
        {
            currentByteIndex = i;
            currentByteOffset = baseOffset + i;
            return FIT_FALSE;
        }

        const FIT_UINT8* p = buffer + i;
        const FIT_UINT8* const end = buffer + n;

        for ( ; p < end; ++p )
        {
            decodeReturn = ReadByte((FIT_UINT8)*p);

            if ( decodeReturn == RETURN_CONTINUE )
            {
                continue;
            }

            const FIT_UINT32 byteIndex = (FIT_UINT32)(p - buffer);
            const FIT_UINT32 byteOffset = baseOffset + byteIndex;
            currentByteIndex = byteIndex;
            currentByteOffset = byteOffset;

